"""Helices generated by repeating one backbone conformation (Algorithm 7.2.1).

A chain of 24 residues with identical (phi, psi) and trans peptides is built with standard bond
lengths and angles. The rigid motion that carries the N, CA, C frame of residue i onto that of
residue i+1 is found by least squares (Kabsch); its rotation angle and its translation along the
rotation axis are the twist per residue and the rise per residue (Chasles' theorem).
A: CA traces of five regular conformations viewed perpendicular to the computed axis.
B: helical net of the alpha helix (the cylinder through the CA atoms cut along a line and unrolled),
with the i -> i+3 and i -> i+4 neighbours. C: computed parameters.
"""

import numpy as np
import wikibio as bio
from wikibio import charts

P = bio.P
FT = bio.core.FONT


def place(a, b, c, bond, angle, torsion):
    angle, torsion = np.radians(angle), np.radians(torsion)
    bc = (c - b) / np.linalg.norm(c - b)
    n = np.cross(b - a, bc)
    n /= np.linalg.norm(n)
    m = np.cross(n, bc)
    return c + bond * (-np.cos(angle) * bc + np.sin(angle) * np.cos(torsion) * m
                       + np.sin(angle) * np.sin(torsion) * n)


def chain(phi, psi, n=24, omega=180.0):
    """Backbone atoms N, CA, C of n residues with constant dihedral angles."""
    X = [np.array([0.0, 0.0, 0.0]), np.array([1.458, 0.0, 0.0])]
    a = np.radians(111.0)
    X.append(X[1] + 1.525 * np.array([-np.cos(a), np.sin(a), 0.0]))
    # each new atom: (bond, angle, torsion) along N-CA-C-N-CA-C ...
    spec = [(1.329, 116.2, psi), (1.458, 121.7, omega), (1.525, 111.0, phi)]
    k = 0
    while len(X) < 3 * n:
        b, ang, tor = spec[k % 3]
        X.append(place(X[-3], X[-2], X[-1], b, ang, tor))
        k += 1
    return np.array(X).reshape(n, 3, 3)


def kabsch(A, B):
    """Rotation R and translation t with B = A R^T + t (least squares)."""
    ca, cb = A.mean(0), B.mean(0)
    H = (A - ca).T @ (B - cb)
    U, S, Vt = np.linalg.svd(H)
    d = np.sign(np.linalg.det(Vt.T @ U.T))
    R = Vt.T @ np.diag([1, 1, d]) @ U.T
    return R, cb - R @ ca


def helix_params(phi, psi):
    X = chain(phi, psi)
    R, t = kabsch(X[5], X[6])
    theta = np.arccos(np.clip((np.trace(R) - 1) / 2, -1, 1))
    w = np.array([R[2, 1] - R[1, 2], R[0, 2] - R[2, 0], R[1, 0] - R[0, 1]])
    u = w / np.linalg.norm(w) if np.linalg.norm(w) > 1e-9 else np.array([0, 0, 1.0])
    d = t @ u
    if d < 0:                       # orient the axis along the chain
        u, d, theta = -u, -d, -theta
    # theta > 0: right-handed rotation about u for a positive rise
    ca = X[:, 1]
    c0 = ca.mean(0)
    rel = ca - c0
    radial = rel - np.outer(rel @ u, u)
    radius = np.sqrt((radial ** 2).sum(1)).mean()
    return X, u, np.degrees(theta), d, radius


CONF = [("α helix", -57, -47, "protein"), ("3$_{10}$ helix", -49, -26, "enzyme"),
        ("π helix", -57, -70, "receptor"), ("PPII", -75, 145, "drug"), ("β strand", -139, 135, "channel")]

fig, ax = bio.canvas(25.0, 8.8)
bio.panel(ax, "A", (0.1, 8.7))
res = []
for j, (name, f, s, tok) in enumerate(CONF):
    X, u, th, d, rad = helix_params(f, s)
    res.append((name, f, s, th, d, rad))
    ca = X[:, 1]
    # frame: z along axis, x perpendicular
    z = u
    tmp = np.array([1.0, 0, 0]) if abs(u[0]) < 0.9 else np.array([0, 1.0, 0])
    x = np.cross(z, tmp)
    x /= np.linalg.norm(x)
    y = np.cross(z, x)
    nres = int(round(24.0 / d))              # about 2.4 nm of chain for every conformation
    c = ca[:nres] - ca[:nres].mean(0)
    px, py, pz = c @ x, c @ y, c @ z
    x0, y0, sc = 1.3 + 2.4 * j, 4.75, 0.2    # canvas units per angstrom
    for i in range(nres - 1):
        front = (py[i] + py[i + 1]) / 2 > 0
        ax.plot([x0 + sc * px[i], x0 + sc * px[i + 1]], [y0 + sc * pz[i], y0 + sc * pz[i + 1]],
                color=P.edge(tok) if front else P.fill(tok), lw=2.2 if front else 1.6,
                solid_capstyle="round", zorder=6 if front else 4)
    ax.scatter(x0 + sc * px, y0 + sc * pz, s=10, color=P.fill(tok), edgecolor=P.edge(tok), lw=0.6, zorder=7)
    ax.plot([x0, x0], [y0 - 2.6, y0 + 2.6], color=P.muted(), lw=0.6, ls=":", zorder=2)
    bio.label(ax, (x0, 1.55), name, size="small")
    bio.label(ax, (x0, 1.05), f"φ, ψ = {f}°, {s}°", size="tiny", color=P.muted())
bio.scale_bar(ax, (0.4, 0.45), 0.2 * 10, "1 nm", size="tiny")

# B: helical net of the alpha helix
bio.panel(ax, "B", (12.6, 8.7))
X, u, th, d, rad = helix_params(-57, -47)
pb = charts.axes_at(ax, (13.8, 1.0, 4.6, 6.6))
nres = 18
az = np.radians(th) * np.arange(nres)
arc = (rad * az) % (2 * np.pi * rad)
zz = d * np.arange(nres)
for i in range(nres):
    for step, ls, tok in ((3, ":", "neutral"), (4, "-", "highlight")):
        j = i + step
        if j < nres:
            dx = arc[j] - arc[i]
            if abs(dx) < np.pi * rad:
                pb.plot([arc[i], arc[j]], [zz[i], zz[j]], color=P.edge(tok), lw=1.0, ls=ls, zorder=2)
pb.scatter(arc, zz, s=120, color=P.fill("protein"), edgecolor=P.edge("protein"), zorder=4)
for i in range(nres):
    pb.text(arc[i], zz[i], str(i + 1), ha="center", va="center", fontsize=FT["tiny"], color=P.on_fill(), zorder=5)
pb.set_xlim(-0.6, 2 * np.pi * rad + 0.6)
pb.set_ylim(-1.0, d * nres + 0.5)
charts.style_axes(pb, "arc length around axis / Å", "height along axis / Å", box=True)
charts.title(pb, "α helix: helical net")
pb.plot([], [], color=P.edge("highlight"), lw=1.0, label="i → i+4 (H bond)")
pb.plot([], [], color=P.edge("neutral"), lw=1.0, ls=":", label="i → i+3")
pb.legend(loc="upper left", fontsize=FT["tiny"], frameon=False, labelcolor=P.ink(), bbox_to_anchor=(0.0, 1.12), ncol=2)

# C: parameter table
bio.panel(ax, "C", (19.4, 8.7))
rows = [("", "n", "d / Å", "p / Å", "r$_{CA}$ / Å")]
for name, f, s, t, dd, r in res:
    n = 360.0 / t
    rows.append((name, f"{n:+.2f}" if abs(abs(n) - 2) > 0.05 else "2.00", f"{dd:.2f}", f"{abs(n) * dd:.1f}", f"{r:.2f}"))
for i, row in enumerate(rows):
    y = 7.6 - 0.75 * i
    for k, cell in enumerate(row):
        xk = [19.6, 21.9, 23.0, 24.0, 25.0][k]
        ax.text(xk, y, cell, ha="left" if k == 0 else "right", va="center",
                fontsize=FT["tiny"], color=P.ink(), weight="bold" if i == 0 else "normal")
ax.plot([19.6, 25.0], [7.25, 7.25], color=P.muted(), lw=0.6)
ax.text(19.6, 2.9, "n: residues per turn (+ right-,\n− left-handed); d: rise per\nresidue; p = |n| d: pitch;\nr$_{CA}$: radius of the CA atoms",
        fontsize=FT["tiny"], color=P.muted(), va="top")
